import{_ as t,o,c as a,a0 as n}from"./chunks/framework.D4fUSYzX.js";const w=JSON.parse('{"title":"ADR 0019: The Main view holds two lists and one detail pane","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0019-the-main-view-holds-two-lists-and-one-detail-pane.md","filePath":"adr/0019-the-main-view-holds-two-lists-and-one-detail-pane.md"}'),s={name:"adr/0019-the-main-view-holds-two-lists-and-one-detail-pane.md"};function i(h,e,l,d,r,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0019-the-main-view-holds-two-lists-and-one-detail-pane" tabindex="-1">ADR 0019: The Main view holds two lists and one detail pane <a class="header-anchor" href="#adr-0019-the-main-view-holds-two-lists-and-one-detail-pane" aria-label="Permalink to &quot;ADR 0019: The Main view holds two lists and one detail pane&quot;">​</a></h1><p>Status: accepted Date: 2026-09-14</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR 0013 merged the Tickets and Consultation views into one Main surface with two accordion sections: the expanded section owned both list and detail panes, the collapsed one shrank to a header row, and <code>t</code> and <code>v</code> switched the expansion. That shape keeps the operator inside one section at a time: to check the Consultation list, the operator switches away from the ticket list, and the list they were reading leaves the screen.</p><p>The operator&#39;s real need is to see the pipeline and the Consultation state at the same time (issue #49): the ticket list and the Consultation list are two facets of one board, and the detail of whichever item the cursor holds is the thing they are working on. One item is selected at a time across both lists, so the two sections never need two detail panes.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Both sections are lists, and both can be expanded at once.</strong> The Main view&#39;s first body row is the Ticket section&#39;s header, run the full terminal width, so its counts stay whole on a small terminal: the narrow count form is the longest text the minimum width holds. Below it the left side stacks the Ticket list over the Consultation list, the Consultation header between them. Both start expanded. Each section is independently collapsable with <code>x</code> or a click on its header: collapsing shrinks the section to its header row and its rows leave the navigation flow, and the toggle is reversible. The <code>t</code> and <code>v</code> view-switch keys are gone.</p><p><strong>The detail pane is one, and it follows the selection.</strong> The right side is a single context-dependent pane: it shows the ticket detail while the cursor holds a ticket, and the Consultation detail while it holds a Consultation. Collapsing the section that holds the selection keeps the selection and its detail: the detail pane is a right-side fact about the cursor, not a child of the section that owns it.</p><p><strong>Navigation is one continuous flow.</strong> Up and down move the cursor through the visible rows and cross the section boundary when the sections are adjacent; left and right still move the focus between the list and the detail. Crossing out of the Ticket list walks the cursor off its last row the way a page turn leaves the page, so the walk never erases the scroll offset the operator parked on that ticket.</p><p><strong>The Ticket header carries steady pipeline counts.</strong> It always shows open, running, and awaiting, computed from the in-memory ticket array on each render, with the held count appended only when it is non-zero so the alert stands out against the steady shape. The Consultation header&#39;s attention facts are unchanged, and the two headers now share one visual pattern.</p><h2 id="considered-alternatives" tabindex="-1">Considered alternatives <a class="header-anchor" href="#considered-alternatives" aria-label="Permalink to &quot;Considered alternatives&quot;">​</a></h2><ul><li>Keep ADR 0013&#39;s accordion: one section owns both panes, <code>t</code> and <code>v</code> switch. Rejected: the operator&#39;s other list is always off-screen, and the switch costs the visual continuity of the list they were reading.</li><li>One merged list with two groups and no independent collapse. Rejected: the operator cannot free vertical space for the list they are working in; the per-section minimum also keeps a small terminal usable for both headers at once.</li><li>Keep the section&#39;s own detail pane alongside the shared one (two detail panes, one per section). Rejected: only one item is selected at a time, so a second pane would show a stale copy of a detail the cursor no longer holds.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>ADR 0013&#39;s decisions that one expanded section owns both list and detail, and that <code>t</code> and <code>v</code> switch sections, are superseded by this ADR. Its surviving decisions hold: one Main surface, one Message line, one Action bar, one control catalogue, Consultation attention on its header.</li><li>The minimum terminal height rises: both headers, two section minimums, the Message line, and the Action bar must fit, so 40 columns by 19 rows is the shortest terminal the Main frame renders.</li><li>The <code>x</code> key moves from closing the Consultation to toggling the section under the cursor; the Consultation close takes <code>z</code>.</li><li>A section below its minimum rows collapses rather than vanishing, so both headers stay on screen on a small terminal.</li></ul>',14)])])}const u=t(s,[["render",i]]);export{w as __pageData,u as default};
